import{_ as i,o as e,c as a,al as n}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"uORB Documentation Standard","description":"","frontmatter":{},"headers":[],"relativePath":"en/uorb/uorb_documentation.md","filePath":"en/uorb/uorb_documentation.md"}'),t={name:"en/uorb/uorb_documentation.md"};function l(o,s,d,p,h,r){return e(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="uorb-documentation-standard" tabindex="-1">uORB Documentation Standard <a class="header-anchor" href="#uorb-documentation-standard" aria-label="Permalink to &quot;uORB Documentation Standard&quot;">​</a></h1><p>This topic demonstrates and explains how to document uORB messages.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>At time of writing many topics have not been updated.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <a href="./../msg_docs/AirspeedValidated">AirspeedValidated</a> message shown below is a good example of a uORB topic that has been documented to the current standard.</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Validated airspeed</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Provides information about airspeed (indicated, true, calibrated) and the source of the data.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Used by controllers, estimators and for airspeed reporting to operator.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uint32 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MESSAGE_VERSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uint64 timestamp </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [us] Time since system start</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 indicated_airspeed_m_s </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [m/s] [@invalid NaN] Indicated airspeed (IAS)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 calibrated_airspeed_m_s </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [m/s] [@invalid NaN] Calibrated airspeed (CAS)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 true_airspeed_m_s </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [m/s] [@invalid NaN] True airspeed (TAS)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 airspeed_source </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [@enum SOURCE] Source of currently published airspeed values</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_DISABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Disabled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_GROUND_MINUS_WIND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Ground speed minus wind</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_SENSOR_1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Sensor 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_SENSOR_2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Sensor 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_SENSOR_3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Sensor 3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_SYNTHETIC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Synthetic airspeed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 calibrated_ground_minus_wind_m_s </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [m/s] [@invalid NaN] CAS calculated from groundspeed - windspeed, where windspeed is estimated based on a zero-sideslip assumption</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 calibraded_airspeed_synth_m_s </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [m/s] [@invalid NaN] Synthetic airspeed</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 airspeed_derivative_filtered </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [m/s^2] Filtered indicated airspeed derivative</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 throttle_filtered </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [-] Filtered fixed-wing throttle</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 pitch_filtered </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [rad] Filtered pitch</span></span></code></pre></div><p>The main things to note are:</p><ul><li>Documentation is added using formatted uORB comments. Any text on a line after the <code>#</code> character is a comment, except for lines that start with the text <code># TOPIC</code> (which indicates a multi-topic message).</li><li>The message starts with a comment block consisting of short description (mandatory), followed by a longer description and then a space.</li><li>Field and constants almost all have comments. The comments are added on the same line as the field/constant, separated by one space.</li><li>Fields: <ul><li>Comments are all on the same line as the field (extra lines become internal comments).</li><li>Comments start with metadata, such as the units (<code>[m/s]</code>, <code>[rad/s]</code>) or allowed values (<code>[@enum SOURCE]</code>), and can also list invalid values (<code>[@invalid NaN]</code>) and allowed ranges (<code>[@range min, max]</code>).</li><li>Units are required except for boolean fields or for fields with an enum value. <code>[-]</code> is used to indicate unitless fields.</li><li>Comments follow the metadata after a space. The line should not be terminated in a full stop.</li></ul></li><li>Constants: <ul><li>Don&#39;t have metadata: the description follows the comment marker after one space.</li><li>Some constants, such as <code>MESSAGE_VERSION</code>, don&#39;t need documentation because they are standardized.</li><li>Constants with the same name prefix are grouped together as enums after the associated field.</li></ul></li></ul><p>The following sections expand on the allowed formats.</p><h2 id="message-description" tabindex="-1">Message Description <a class="header-anchor" href="#message-description" aria-label="Permalink to &quot;Message Description&quot;">​</a></h2><p>Every message should start with a comment block that describes the message:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Short description (mandatory)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Longer description for the message if needed.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Can be multiline, and should have punctuation.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Should be followed by an empty line.</span></span></code></pre></div><p>This consists of a mandatory short description, optionally followed by an empty comment line, and then a longer description.</p><p>Short description (mandatory):</p><ul><li>A succinct explanation for the purpose of the message.</li><li>Usually just one line without a terminating full stop.</li><li>Minimally it may just mirror the message name.</li><li>For example, <a href="./../msg_docs/AirspeedValidated"><code>AirspeedValidated</code></a> above has the short description <code>Validated airspeed</code>.</li></ul><p>Long description (Optional):</p><ul><li>Additional context required to understand how the message is used.</li><li>In particular this should be anything that can&#39;t be inferred from the name, fields or constants, such as the publishers and expected consumers. It might also cover whether the message is only used for a particular frame type or mode.</li><li>The message is often multiline and contains punctuation.</li><li>May include comment lines that are empty, in order to indicate paragraphs.</li></ul><p>Both short and long descriptions may be multi-line. Single line descriptions should not include a terminating full stop, but multiline comments should do so.</p><p>The message description block ends at the first non-comment line, which should be an empty line, but might be a field or constant. Any subsequent comment lines are considered &quot;internal comments&quot;.</p><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><p>A typical field comment looks like this:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float32 indicated_airspeed_m_s </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [m/s] [@invalid NaN] Indicated airspeed (IAS)</span></span></code></pre></div><p>Field comments must all be on the same line as the field, and consist of optional metadata followed by a description:</p><ul><li><code>metadata</code> (Optional) <ul><li>Information about the field units and allowed values: <ul><li><code>[&lt;unit&gt;]</code><ul><li>The unit of measurement inside square brackets (note, no <code>@</code> delineator indicates a unit), such as <code>[m]</code> for metres. <ul><li>Allowed units include: <code>m</code>, <code>m/s</code>, <code>m/s^2</code>, <code>rad</code>, <code>rad/s</code>, <code>rpm</code>, <code>V</code>, <code>A</code>, <code>mA</code>, <code>mAh</code>, <code>W</code>, <code>dBm</code>, <code>s</code>, <code>ms</code>, <code>us</code>, <code>Ohm</code>, <code>MB</code>, <code>Kb/s</code>, <code>degC</code>, <code>Pa</code>.</li><li>Units are required unless clearly invalid, such as when the field is a boolean, or is an enum value.</li><li>Unitless values should be specified as <code>[-]</code>. Note though that units are not required for boolean fields or enum fields.</li></ul></li></ul></li><li><code>[@enum &lt;enum_name&gt;]</code><ul><li>The <code>enum_name</code> gives the prefix of constant values in the message that can be assigned to the field. Note that enums in uORB are just a naming convention: they are not explicitly declared. Multiple enum names allowed for a field indicates a possible error in the field design.</li></ul></li><li><code>[@range &lt;lower_value&gt;, &lt;upper_value&gt;]</code><ul><li>The allowed range of the field, specified as a <code>lower_value</code> and/or an <code>upper_value</code>. Either value can be omitted to indicate an unbounded upper or lower value. For example <code>[@range 0, 3]</code>, <code>[@range 5.3, ]</code>, <code>[@range , 3]</code>.</li></ul></li><li><code>[@invalid &lt;value&gt; &lt;description&gt;]</code><ul><li>The <code>value</code> to set the field to indicate that the field doesn&#39;t contain valid data, such as <code>[@invalid NaN]</code>. The <code>description</code> is optional, and might be used to indicate the conditions under which data is invalid.</li></ul></li><li><code>[@frame &lt;value&gt;]</code><ul><li>The <code>frame</code> in which the field is set, such as <code>[@frame NED]</code> or <code>[@frame Body]</code>.</li></ul></li></ul></li></ul></li><li><code>description</code><ul><li>A concise description of the purpose of the field, and including any important information that can&#39;t be inferred from the name! Use a capital first letter, and omit the full stop if the description is a single sentence. Multiple sentences may also omit the final full stop.</li></ul></li></ul><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><p>Constants follow the documentation conventions as fields except they only have a description (no metadata). Documentation for a constant might look like this:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_GROUND_MINUS_WIND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Ground speed minus wind</span></span></code></pre></div><p>Constants are often grouped together following a field as enum values. Note below how the prefix <code>SOURCE</code> for the values is specified as an enum against the <em>field</em>.</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 airspeed_source </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [@enum SOURCE] Source of currently published airspeed values</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_DISABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Disabled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">int8 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SOURCE_GROUND_MINUS_WIND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Ground speed minus wind</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><p>A small number of constants have a standardised meaning and do not require documentation. These are:</p><ul><li><code>ORB_QUEUE_LENGTH</code></li><li><code>MESSAGE_VERSION</code></li></ul><h3 id="topics" tabindex="-1"><code># TOPICS</code> <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;\`# TOPICS\`&quot;">​</a></h3><p>The prefix <code># TOPICS</code> is used to indicate topic names for multi-topic messages. For example, the <a href="./../msg_docs/VehicleGlobalPosition">VehicleGlobalPosition.msg</a> message definition is used to define the topic ids as shown:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># TOPICS vehicle_global_position vehicle_global_position_groundtruth external_ins_global_position</span></span>
<span class="line"><span># TOPICS estimator_global_position</span></span>
<span class="line"><span># TOPICS aux_global_position</span></span></code></pre></div><p>At time of writing there is no format for documenting these.</p>`,35)])])}const u=i(t,[["render",l]]);export{k as __pageData,u as default};
